"""Real isolated PG role, recovery, fencing and publication control checks."""
import importlib.util,json,pathlib,uuid,time,concurrent.futures
path=pathlib.Path(__file__).with_name('verify-market-cause-budget.py')
spec=importlib.util.spec_from_file_location('base',path);b=importlib.util.module_from_spec(spec);spec.loader.exec_module(b)
sql,check,run=b.sql,b.check,b.run
def main():
 r=run(['docker','run','--detach','--rm','--name',b.NAME,'--network','none','--memory','512m','--cpus','1.5','--tmpfs','/var/lib/postgresql/data:rw,nosuid,size=256m','-e','POSTGRES_HOST_AUTH_METHOD=trust','postgres:17-alpine']);assert r.returncode==0,r.stderr
 try:
  for _ in range(100):
   logs=run(['docker','logs',b.NAME]);ready='init process complete; ready for start up' in logs.stdout+logs.stderr
   if ready and run(['docker','exec',b.NAME,'pg_isready','-U','postgres']).returncode==0:break
   time.sleep(.2)
  else:raise RuntimeError('database not ready')
  sql('CREATE ROLE anon NOLOGIN;CREATE ROLE authenticated NOLOGIN;CREATE ROLE service_role NOLOGIN BYPASSRLS;GRANT USAGE ON SCHEMA public TO anon,authenticated,service_role;')
  for name in ['proposals/market_cause_budget_v1.sql','proposals/market_cause_jobs_v1.sql','migrations/20261031_market_cause_operations.sql','migrations/20261031_market_cause_retry_days.sql','migrations/20261031_market_cause_company_publication.sql']:sql((b.ROOT/'supabase'/name).read_text())
  check('publication disabled by default',json.loads(sql('select public.read_market_cause_official();','service_role'))=={'enabled':False,'snapshots':[]})
  for role in ['anon','authenticated']:
   for fn in ['read_market_cause_companies','read_market_cause_official','market_cause_recovery_due','observe_market_cause_day']:sql(f'select public.{fn}();',role,True)
   sql('select * from market_cause_private.daily_observations;',role,True)
  check('browser roles cannot inspect or mutate operations',True)
  sql('UPDATE market_cause_private.worker_control SET enabled=true;UPDATE market_cause_private.budget_control SET enabled=true;')
  owner=str(uuid.uuid4());h='a'*64;event='collection:INTC:2026-10-31'
  def claim(key='retry',o=owner,e=event):return json.loads(sql(f"select public.claim_market_cause_job('{key}','{e}','{h}','{o}');",'service_role'))
  def publish(fence,revision=0,retry=True,key='retry',o=owner,official=False):
   payload=json.dumps({'disposition':'facts_only','claims':[],'retryable':retry,'snapshot':{'decision':{'reasonCodes':['collection_analysis_failed']},'official':{'status':'verified','checkedAt':'2026-10-31T00:00:00Z','release':None} if official else None}})
   return json.loads(sql(f"select public.publish_market_cause_shadow('{key}','{h}','{o}',{fence},{revision},'{payload}');",'service_role'))
  first=claim();check('failure saved with retry state',publish(first['fence'])['status']=='stored')
  check('failure is not marked finished',sql("select status from market_cause_private.jobs where job_key='retry';")=='failed')
  check('cooldown blocks immediate retry',claim()['status']=='busy')
  check('queue respects cooldown',json.loads(sql('select public.market_cause_recovery_due();','service_role'))==[])
  sql("UPDATE market_cause_private.jobs SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE job_key='retry';")
  check('due queue exposes only fixed event key',json.loads(sql('select public.market_cause_recovery_due();','service_role'))==[{'event_key':event}])
  with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:results=list(pool.map(lambda _:claim(),range(8)))
  check('concurrent recovery claims once',sum(x['status']=='claimed' for x in results)==1)
  second=next(x for x in results if x['status']=='claimed');check('recovery advances fence',second['fence']==first['fence']+1)
  check('old worker cannot finalize failure',publish(first['fence'],1)['status']=='stale_worker')
  check('second failure preserves immutable history',publish(second['fence'],1)['status']=='stored' and sql("select count(*) from market_cause_private.shadow_versions;")=='2')
  sql("UPDATE market_cause_private.jobs SET next_attempt_at=clock_timestamp()-interval '1 second' WHERE job_key='retry';")
  check('two-attempt ceiling stops repeated failures',claim()['status']=='attempts_exhausted')
  check('exhausted work excluded from recovery',json.loads(sql('select public.market_cause_recovery_due();','service_role'))==[])
  sql("UPDATE market_cause_private.jobs SET attempt_day=(clock_timestamp() AT TIME ZONE 'UTC')::date-1 WHERE job_key='retry';")
  check('next UTC day may retry without resetting the fence',claim()['fence']==second['fence']+1)
  check('next-day retry starts a fresh bounded attempt count',sql("select attempts from market_cause_private.jobs where job_key='retry';")=='1')
  p=claim('official',e='official:fed');publish(p['fence'],key='official',retry=False,official=True)
  sql('UPDATE market_cause_private.publication_control SET official_facts=true;')
  public=json.loads(sql('select public.read_market_cause_official();','service_role'))
  check('public read only projects the two registered official heads',len(public['snapshots'])==1 and 'collection' not in json.dumps(public))
  sql('UPDATE market_cause_private.publication_control SET official_facts=false;')
  check('kill switch removes publication immediately',json.loads(sql('select public.read_market_cause_official();','service_role'))['snapshots']==[])
  check('company publication disabled by default',json.loads(sql('select public.read_market_cause_companies();','service_role'))=={'enabled':False,'release':None,'snapshots':[]})
  p=claim('company',e='facts:INTC');publish(p['fence'],key='company',retry=False)
  p=claim('private-company',e='sec:INTC');publish(p['fence'],key='private-company',retry=False)
  sql('UPDATE market_cause_private.publication_control SET company_facts=true;')
  published=json.loads(sql('select public.read_market_cause_companies();','service_role'))
  check('enabled read excludes private narrative without a release certificate',len(published['snapshots'])==1 and published['snapshots'][0]['kind']=='facts' and published['release'] is None)
  sql('UPDATE market_cause_private.publication_control SET company_facts=false;')
  check('company kill switch removes cards',json.loads(sql('select public.read_market_cause_companies();','service_role'))['snapshots']==[])
  check('first daily observation stored',json.loads(sql('select public.observe_market_cause_day();','service_role'))['status']=='recorded')
  check('duplicate observation is read-only',json.loads(sql('select public.observe_market_cause_day();','service_role'))['status']=='existing' and sql('select count(*) from market_cause_private.daily_observations;')=='1')
  check('observation contains no portfolio tables',not any(s in sql('select report::text from market_cause_private.daily_observations;') for s in ['holdings','email','user_id']))
  sql('UPDATE market_cause_private.worker_control SET enabled=false;')
  check('disabled worker does not recover or observe',json.loads(sql('select public.market_cause_recovery_due();','service_role'))==[] and json.loads(sql('select public.observe_market_cause_day();','service_role'))['status']=='disabled')
  out=b.ROOT/'artifacts/market-explanation-engine-20261031';out.mkdir(exist_ok=True)
  (out/'operations-db.json').write_text(json.dumps({'checks':b.checks,'productionChanged':False,'database':'disposable PostgreSQL17'},indent=2)+'\n')
  print(len(b.checks),'isolated operations checks passed')
 finally:run(['docker','rm','-f',b.NAME])
if __name__=='__main__':main()
